import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Plus, 
  Check, 
  X, 
  Edit3, 
  Trash2, 
  Target, 
  Calendar,
  Clock,
  CheckCircle2,
  Circle,
  RotateCcw
} from 'lucide-react';
import { useUser } from '../context/UserContext';
import { useNotifications } from '../context/NotificationContext';
import './DailyGoals.css';

const DailyGoals = () => {
  const { awardPoints } = useUser();
  const { showToast } = useNotifications();

  const [goals, setGoals] = useState([]);
  const [newGoal, setNewGoal] = useState('');
  const [editingGoal, setEditingGoal] = useState(null);
  const [editText, setEditText] = useState('');
  const [showAddForm, setShowAddForm] = useState(false);

  // Load goals from localStorage on component mount
  useEffect(() => {
    const today = new Date().toDateString();
    const savedGoals = localStorage.getItem(`daily_goals_${today}`);

    if (savedGoals) {
      try {
        setGoals(JSON.parse(savedGoals));
      } catch (error) {
        console.error('Error loading daily goals:', error);
        setGoals([]);
      }
    }
  }, []);

  // Save goals to localStorage whenever goals change
  useEffect(() => {
    const today = new Date().toDateString();
    localStorage.setItem(`daily_goals_${today}`, JSON.stringify(goals));
  }, [goals]);

  // Calculate progress
  const completedGoals = goals.filter(goal => goal.completed).length;
  const totalGoals = goals.length;
  const progressPercentage = totalGoals > 0 ? (completedGoals / totalGoals) * 100 : 0;

  // Add new goal
  const handleAddGoal = (e) => {
    e.preventDefault();
    if (newGoal.trim()) {
      const goal = {
        id: Date.now(),
        text: newGoal.trim(),
        completed: false,
        createdAt: new Date().toISOString(),
        completedAt: null
      };

      setGoals(prev => [...prev, goal]);
      setNewGoal('');
      setShowAddForm(false);
      showToast('Goal added successfully!', 'success');
    }
  };

  // Toggle goal completion
  const toggleGoal = (goalId) => {
    setGoals(prev => prev.map(goal => {
      if (goal.id === goalId) {
        const wasCompleted = goal.completed;
        const updatedGoal = {
          ...goal,
          completed: !goal.completed,
          completedAt: !goal.completed ? new Date().toISOString() : null
        };

        // Award points for completing goal
        if (!wasCompleted && updatedGoal.completed) {
          awardPoints(10, 'Daily goal completed');
          showToast('Goal completed! +10 points', 'success');
        }

        return updatedGoal;
      }
      return goal;
    }));
  };

  // Delete goal
  const deleteGoal = (goalId) => {
    setGoals(prev => prev.filter(goal => goal.id !== goalId));
    showToast('Goal deleted', 'info');
  };

  // Start editing goal
  const startEditing = (goal) => {
    setEditingGoal(goal.id);
    setEditText(goal.text);
  };

  // Save edited goal
  const saveEdit = () => {
    if (editText.trim()) {
      setGoals(prev => prev.map(goal => 
        goal.id === editingGoal 
          ? { ...goal, text: editText.trim() }
          : goal
      ));
      setEditingGoal(null);
      setEditText('');
      showToast('Goal updated successfully!', 'success');
    }
  };

  // Cancel editing
  const cancelEdit = () => {
    setEditingGoal(null);
    setEditText('');
  };

  // Clear completed goals
  const clearCompletedGoals = () => {
    const completedCount = completedGoals;
    setGoals(prev => prev.filter(goal => !goal.completed));
    showToast(`${completedCount} completed goals cleared!`, 'info');
  };

  // Reset all goals
  const resetAllGoals = () => {
    if (window.confirm('Are you sure you want to reset all daily goals? This action cannot be undone.')) {
      setGoals([]);
      showToast('All goals reset!', 'warning');
    }
  };

  const getCurrentDate = () => {
    return new Date().toLocaleDateString('en-US', {
      weekday: 'long',
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
  };

  return (
    <motion.div 
      className="daily-goals-container"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5 }}
    >
      <div className="daily-goals-wrapper">
        {/* Header */}
        <div className="goals-header">
          <div className="header-content">
            <div className="header-icon">
              <Target size={32} />
            </div>
            <div className="header-text">
              <h1>Daily Learning Goals</h1>
              <p className="header-date">
                <Calendar size={16} />
                {getCurrentDate()}
              </p>
            </div>
          </div>

          <div className="header-actions">
            <button
              onClick={() => setShowAddForm(true)}
              className="add-goal-btn"
            >
              <Plus size={20} />
              Add Goal
            </button>
          </div>
        </div>

        {/* Progress Section */}
        <div className="progress-section">
          <div className="progress-header">
            <h3>Today's Progress</h3>
            <span className="progress-text">
              {completedGoals} of {totalGoals} goals completed
            </span>
          </div>

          <div className="progress-bar-container">
            <div className="progress-bar">
              <motion.div 
                className="progress-fill"
                initial={{ width: 0 }}
                animate={{ width: `${progressPercentage}%` }}
                transition={{ duration: 0.5, ease: "easeOut" }}
              />
            </div>
            <span className="progress-percentage">
              {Math.round(progressPercentage)}%
            </span>
          </div>

          {totalGoals > 0 && (
            <div className="progress-actions">
              {completedGoals > 0 && (
                <button
                  onClick={clearCompletedGoals}
                  className="clear-completed-btn"
                >
                  <CheckCircle2 size={16} />
                  Clear Completed ({completedGoals})
                </button>
              )}

              <button
                onClick={resetAllGoals}
                className="reset-all-btn"
              >
                <RotateCcw size={16} />
                Reset All
              </button>
            </div>
          )}
        </div>

        {/* Add Goal Form */}
        <AnimatePresence>
          {showAddForm && (
            <motion.div
              className="add-goal-form"
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: 'auto' }}
              exit={{ opacity: 0, height: 0 }}
              transition={{ duration: 0.3 }}
            >
              <form onSubmit={handleAddGoal}>
                <div className="form-group">
                  <input
                    type="text"
                    value={newGoal}
                    onChange={(e) => setNewGoal(e.target.value)}
                    placeholder="Enter your learning goal (e.g., Watch 2 React tutorials)"
                    className="goal-input"
                    autoFocus
                  />
                </div>
                <div className="form-actions">
                  <button
                    type="button"
                    onClick={() => {
                      setShowAddForm(false);
                      setNewGoal('');
                    }}
                    className="cancel-btn"
                  >
                    <X size={16} />
                    Cancel
                  </button>
                  <button
                    type="submit"
                    className="save-btn"
                    disabled={!newGoal.trim()}
                  >
                    <Check size={16} />
                    Add Goal
                  </button>
                </div>
              </form>
            </motion.div>
          )}
        </AnimatePresence>

        {/* Goals List */}
        <div className="goals-list">
          {goals.length === 0 ? (
            <div className="empty-state">
              <div className="empty-icon">
                <Target size={64} />
              </div>
              <h3>No goals set for today</h3>
              <p>Add your first learning goal to get started!</p>
              <button
                onClick={() => setShowAddForm(true)}
                className="empty-add-btn"
              >
                <Plus size={20} />
                Add Your First Goal
              </button>
            </div>
          ) : (
            <AnimatePresence>
              {goals.map((goal, index) => (
                <motion.div
                  key={goal.id}
                  className={`goal-item ${goal.completed ? 'completed' : ''}`}
                  initial={{ opacity: 0, x: -20 }}
                  animate={{ opacity: 1, x: 0 }}
                  exit={{ opacity: 0, x: 20 }}
                  transition={{ delay: index * 0.1 }}
                  layout
                >
                  <div className="goal-checkbox">
                    <button
                      onClick={() => toggleGoal(goal.id)}
                      className={`checkbox-btn ${goal.completed ? 'checked' : ''}`}
                    >
                      {goal.completed ? (
                        <CheckCircle2 size={20} />
                      ) : (
                        <Circle size={20} />
                      )}
                    </button>
                  </div>

                  <div className="goal-content">
                    {editingGoal === goal.id ? (
                      <div className="edit-form">
                        <input
                          type="text"
                          value={editText}
                          onChange={(e) => setEditText(e.target.value)}
                          className="edit-input"
                          autoFocus
                        />
                        <div className="edit-actions">
                          <button
                            onClick={saveEdit}
                            className="save-edit-btn"
                            disabled={!editText.trim()}
                          >
                            <Check size={14} />
                          </button>
                          <button
                            onClick={cancelEdit}
                            className="cancel-edit-btn"
                          >
                            <X size={14} />
                          </button>
                        </div>
                      </div>
                    ) : (
                      <>
                        <span className="goal-text">{goal.text}</span>
                        {goal.completed && goal.completedAt && (
                          <span className="completion-time">
                            <Clock size={12} />
                            Completed at {new Date(goal.completedAt).toLocaleTimeString([], {
                              hour: '2-digit',
                              minute: '2-digit'
                            })}
                          </span>
                        )}
                      </>
                    )}
                  </div>

                  <div className="goal-actions">
                    {editingGoal !== goal.id && (
                      <>
                        <button
                          onClick={() => startEditing(goal)}
                          className="edit-btn"
                          title="Edit goal"
                        >
                          <Edit3 size={16} />
                        </button>
                        <button
                          onClick={() => deleteGoal(goal.id)}
                          className="delete-btn"
                          title="Delete goal"
                        >
                          <Trash2 size={16} />
                        </button>
                      </>
                    )}
                  </div>
                </motion.div>
              ))}
            </AnimatePresence>
          )}
        </div>

        {/* Daily Summary */}
        {goals.length > 0 && (
          <div className="daily-summary">
            <div className="summary-stats">
              <div className="stat-item">
                <span className="stat-number">{totalGoals}</span>
                <span className="stat-label">Total Goals</span>
              </div>
              <div className="stat-item">
                <span className="stat-number">{completedGoals}</span>
                <span className="stat-label">Completed</span>
              </div>
              <div className="stat-item">
                <span className="stat-number">{totalGoals - completedGoals}</span>
                <span className="stat-label">Remaining</span>
              </div>
            </div>

            {progressPercentage === 100 && (
              <motion.div
                className="completion-celebration"
                initial={{ opacity: 0, scale: 0.8 }}
                animate={{ opacity: 1, scale: 1 }}
                transition={{ delay: 0.5 }}
              >
                <div className="celebration-icon">🎉</div>
                <h3>Congratulations!</h3>
                <p>You've completed all your daily learning goals!</p>
              </motion.div>
            )}
          </div>
        )}
      </div>
    </motion.div>
  );
};

export default DailyGoals;
